		auto scan_msg = std::make_shared<sensor_msgs::msg::LaserScan>();

		// 固定长度为400，角度分辨率0.9度
		const int FIXED_SIZE = 400;
		const float ANGLE_RESOLUTION = 0.9;  // 度
		const float MATCH_THRESHOLD = ANGLE_RESOLUTION/2;   // 匹配阈值（度）
		
		scan_msg->ranges.resize(FIXED_SIZE);
		scan_msg->intensities.resize(FIXED_SIZE);

		// 初始化为NaN
		std::fill(scan_msg->ranges.begin(), scan_msg->ranges.end(), std::numeric_limits<float>::quiet_NaN());
		std::fill(scan_msg->intensities.begin(), scan_msg->intensities.end(), std::numeric_limits<float>::quiet_NaN());

		scan_msg->header.stamp = node->now();
		scan_msg->header.frame_id = node_lidar.lidar_general_info.frame_id;

		// 固定角度范围：0° 到 359.1° (399 * 0.9)
		scan_msg->angle_min = 0.0;
		scan_msg->angle_max = (FIXED_SIZE - 1) * ANGLE_RESOLUTION * M_PI / 180.0;  // 转换为弧度
		scan_msg->angle_increment = ANGLE_RESOLUTION * M_PI / 180.0;  // 转换为弧度
		scan_msg->scan_time = scan.config.scan_time;
		scan_msg->time_increment = scan.config.time_increment;
		// scan_msg->range_min = scan.config.min_range;
		// scan_msg->range_max = scan.config.max_range;

		scan_msg->range_min = node_lidar.lidar_general_info.min_range;
		scan_msg->range_max = node_lidar.lidar_general_info.max_range;

		// outscan.config.min_range = node_lidar.lidar_general_info.min_range;
		// outscan.config.max_range = node_lidar.lidar_general_info.max_range;

		// 遍历原始数据点，找到最接近的目标索引位置
		for(size_t j = 0; j < scan.points.size(); j++) {
			float point_angle = scan.points[j].angle;  // 已经是度
			
			// 计算这个角度应该对应的索引（四舍五入到最近的0.9度倍数）
			int target_idx = static_cast<int>(std::round(point_angle / ANGLE_RESOLUTION));
			
			// 处理360度边界情况
			if(target_idx >= FIXED_SIZE) {
				target_idx = target_idx % FIXED_SIZE;
			}
			if(target_idx < 0) {
				target_idx = (target_idx % FIXED_SIZE + FIXED_SIZE) % FIXED_SIZE;
			}
			
			// 反转索引（保留原代码的颠倒操作）
			int reversed_idx = FIXED_SIZE - 1 - target_idx;
			
			// 计算实际的目标角度
			float target_angle = target_idx * ANGLE_RESOLUTION;
			
			// 计算角度差（考虑360度周期性）
			float angle_diff = std::abs(point_angle - target_angle);
			if(angle_diff > 180.0) {
				angle_diff = 360.0 - angle_diff;
			}
			
		// 如果角度差在阈值内，填充数据（使用反转后的索引）
		if(angle_diff < MATCH_THRESHOLD) {
			// 如果该位置已有数据，选择角度更接近的
			if(std::isnan(scan_msg->ranges[reversed_idx]) || 
			   angle_diff < std::abs(target_angle - scan.points[j].angle)) {
				// 如果原始range为0，替换为NaN
				float range_value = scan.points[j].range;
				if(range_value == 0.0f) {
					range_value = std::numeric_limits<float>::quiet_NaN();
				}
				scan_msg->ranges[reversed_idx] = range_value;
				scan_msg->intensities[reversed_idx] = scan.points[j].intensity;
			}
		}
		}

		laser_pub->publish(*scan_msg);
   	}
	}
	node_lidar.serial_port->write_data(end_lidar,4);
	return 0;
}

